class zlTrackGroup {
    constructor(own) {
        this.weight = 1;
        this.is_play = false;
        this.track = [];
        this.run_track = [];
        this._owner = own;
    }
    Play(loop) {
        this.is_play = true;
        this.run_track = [];
        if (loop > 0)
            loop--;
        for (let trk of this.track) {
            if (!trk.object) {
                trk.object = this._owner.GetUI(trk.name);
            }
            trk.Play(loop);
            this.run_track.push(trk);
        }
    }
    Stop() {
        this.is_play = false;
        this.run_track = [];
    }
    Parse(parser) {
        while (!parser.EOF()) {
            let toks = parser.Toks();
            parser.NextLine();
            if (toks.length > 0) {
                let tok = toks[0];
                if (tok === "track") {
                    let trk = new zlTrack;
                    if (toks.length > 1) {
                        trk.name = toks[1];
                    }
                    this.track.push(trk);
                    trk.Parse(parser);
                    trk.object = this._owner.GetUI(trk.name);
                }
                else if (tok === 'clone') {
                    //TODO
                }
                else if (tok === 'name') {
                    this.name = toks[1];
                }
                else if (tok === '}') {
                    return parser.current;
                }
            }
        }
        return parser.current;
    }
    Refresh(ti) {
        let work = false;
        for (let i = this.run_track.length - 1; i >= 0; i--) {
            let trk = this.run_track[i];
            if (trk.Refresh(ti)) {
                work = true;
            }
            else {
                this.run_track.splice(i, 1);
            }
        }
        if (!work) {
            this.is_play = false;
        }
        return work;
    }
}

class zlTrackMgr {
    constructor(mgr) {
        this.track = {};
        this.run_track = [];
        this.is_play = false;
        this._owner = mgr;
    }
    Parse(parser) {
        let toks = parser.toks;
        if (toks.length > 0) {
            let tok = toks[0];
            if (tok === "trackgroup") {
                let trk = new zlTrackGroup(this._owner);
                if (toks.length > 1) {
                    trk.name = toks[1];
                }
                trk.Parse(parser);
                this.track[trk.name] = trk;
            }
        }
        return parser.current;
    }
    Play(name, loop, end) {
        let trk = this.track[name];
        trk.on_end = end;
        trk.Play(loop);
        this.run_track.push(trk);
    }
    Refresh(ti) {
        let work = false;
        let remove = false;
        for (let trk of this.run_track) {
            trk.Refresh(ti);
            work = true;
            if (!trk.is_play) {
                remove = true;
                if (trk.on_end) {
                    trk.on_end();
                    trk.on_end = undefined;
                }
                if (this._owner.on_track_end) {
                    this._owner.on_track_end(trk);
                }
            }
        }
        if (remove) {
            for (let i = this.run_track.length - 1; i >= 0; i--) {
                let trk = this.run_track[i];
                if (!trk.is_play) {
                    this.run_track.splice(i, 1);
                }
            }
        }
        this.is_play = work;
        return work;
    }
}

